/**
 * MongoDB collections of the `dinedesk` database. One restaurant: no tenant column. Primary keys are strings (UUID v4,
 * generated by the server). Money is whole dong (integers), stock quantities are doubles rounded to 3 decimals,
 * instants are UTC Dates, local dates are "yyyy-MM-dd" strings in the restaurant's timezone.
 * Order lines, discounts and payments live inside the order document so one atomic write keeps `version` honest.
 */
const mongoose = require('mongoose');

const { Schema } = mongoose;
const Mixed = Schema.Types.Mixed;

const make = (name, collection, def, indexes = []) => {
  const s = new Schema(def, { collection, versionKey: false, minimize: false });
  for (const [spec, opts] of indexes) s.index(spec, opts);
  return mongoose.model(name, s);
};
const stamps = { createdAt: { type: Date, default: Date.now }, updatedAt: { type: Date, default: Date.now } };
const str = (extra = {}) => ({ type: String, default: '', ...extra });

// ---------- accounts & sessions ----------

const Account = make('Account', 'accounts', {
  _id: String,
  email: { type: String, required: true },
  passwordHash: { type: String, required: true },
  name: { type: String, required: true },
  phone: { type: String, default: '' },
  language: { type: String, enum: ['vi', 'en'], default: 'vi' },
  mustChangePassword: { type: Boolean, default: false },
  passwordChangedAt: Date,
  lastLoginAt: Date,
  ...stamps,
}, [[{ email: 1 }, { unique: true }]]);

const Session = make('Session', 'sessions', {
  _id: String,
  accountId: { type: String, required: true },
  refreshHash: { type: String, required: true },
  prevRefreshHash: { type: String, default: null },
  refreshExpiresAt: { type: Date, required: true },
  absoluteExpiresAt: { type: Date, required: true },
  createdAt: { type: Date, default: Date.now },
  lastSeenAt: { type: Date, default: Date.now },
  revokedAt: { type: Date, default: null },
  revokeReason: { type: String, default: null },
  expireAt: { type: Date, required: true },
}, [
  [{ accountId: 1, revokedAt: 1 }, {}],
  [{ expireAt: 1 }, { expireAfterSeconds: 0 }],
]);

const PasswordReset = make('PasswordReset', 'password_resets', {
  _id: String,
  accountId: { type: String, required: true },
  codeHash: { type: String, required: true },
  expiresAt: { type: Date, required: true },
  usedAt: { type: Date, default: null },
  createdAt: { type: Date, default: Date.now },
}, [
  [{ codeHash: 1 }, { unique: true }],
  [{ accountId: 1 }, {}],
  [{ expiresAt: 1 }, { expireAfterSeconds: 86400 }],
]);

const Receipt = make('Receipt', 'receipts', {
  _id: String,
  state: { type: String, default: 'done' },
  status: Number,
  result: Mixed,
  expireAt: { type: Date, required: true },
}, [[{ expireAt: 1 }, { expireAfterSeconds: 0 }]]);

const RateHit = make('RateHit', 'rate_hits', { _id: String, count: { type: Number, default: 0 }, expireAt: Date }, [[{ expireAt: 1 }, { expireAfterSeconds: 0 }]]);

/** Daily order counter: `_id` = `order|yyyy-MM-dd`. */
const Counter = make('Counter', 'counters', { _id: String, seq: { type: Number, default: 0 } });

/** One row per key: `shop`, `rules`. */
const Setting = make('Setting', 'settings', { _id: String, value: { type: Mixed, default: {} }, updatedAt: { type: Date, default: Date.now } });

const AdminAction = make('AdminAction', 'admin_actions', {
  _id: String,
  adminId: { type: String, default: null },
  adminName: str(),
  action: String,
  targetType: str(),
  targetId: { type: String, default: null },
  note: str(),
  at: { type: Date, default: Date.now },
}, [[{ at: -1 }, {}]]);

// ---------- floor ----------

const Area = make('Area', 'areas', { _id: String, name: { type: String, required: true }, sort: { type: Number, default: 0 }, ...stamps });

const Table = make('Table', 'tables', {
  _id: String,
  areaId: { type: String, required: true },
  label: { type: String, required: true },
  seats: { type: Number, default: 4 },
  canMerge: { type: Boolean, default: true },
  status: { type: String, enum: ['free', 'busy', 'billing', 'cleaning'], default: 'free' },
  currentOrderId: { type: String, default: null },
  ...stamps,
}, [[{ label: 1 }, { unique: true }], [{ areaId: 1 }, {}]]);

// ---------- menu ----------

const MenuGroup = make('MenuGroup', 'menu_groups', { _id: String, name: { type: String, required: true }, sort: { type: Number, default: 0 }, ...stamps });

const MenuItem = make('MenuItem', 'menu_items', {
  _id: String,
  groupId: { type: String, required: true },
  code: str(),
  name: { type: String, required: true },
  desc: str(),
  unit: str(),
  price: { type: Number, default: 0 },
  prepMin: { type: Number, default: 0 },
  station: { type: String, enum: ['kitchen', 'bar', 'grill'], default: 'kitchen' },
  status: { type: String, enum: ['on', 'out', 'off'], default: 'on' },
  tags: { type: [String], default: [] },
  options: { type: [Mixed], default: [] },
  recipe: { type: [Mixed], default: [] }, // [{ ingredientId, qty }]
  search: str(),
  ...stamps,
}, [[{ groupId: 1 }, {}], [{ search: 1 }, {}], [{ updatedAt: 1 }, {}]]);

// ---------- stock ----------

const Ingredient = make('Ingredient', 'ingredients', {
  _id: String,
  name: { type: String, required: true },
  unit: str(),
  group: str(),
  minQty: { type: Number, default: 0 },
  supplierId: { type: String, default: null },
  search: str(),
  ...stamps,
}, [[{ search: 1 }, {}]]);

const StockLot = make('StockLot', 'stock_lots', {
  _id: String,
  ingredientId: { type: String, required: true },
  purchaseId: { type: String, default: null },
  received: Number,
  remaining: Number,
  unitCost: { type: Number, default: 0 },
  expiry: { type: String, default: null },
  receivedAt: { type: Date, default: Date.now },
  ...stamps,
}, [[{ ingredientId: 1, remaining: 1 }, {}], [{ purchaseId: 1 }, {}]]);

const StockMove = make('StockMove', 'stock_moves', {
  _id: String,
  ingredientId: { type: String, required: true },
  qty: Number,
  kind: { type: String, enum: ['receive', 'sale', 'waste', 'count'] },
  note: str(),
  orderId: { type: String, default: null }, // sale moves: which order, and which lots were drawn (to undo on reopen)
  lots: { type: [Mixed], default: [] },
  reversed: { type: Boolean, default: false },
  at: { type: Date, default: Date.now },
}, [[{ ingredientId: 1, at: -1 }, {}], [{ orderId: 1 }, {}], [{ kind: 1, at: -1 }, {}], [{ at: -1 }, {}]]);

const Supplier = make('Supplier', 'suppliers', { _id: String, name: { type: String, required: true }, phone: str(), items: str(), note: str(), ...stamps });

const Purchase = make('Purchase', 'purchases', {
  _id: String,
  supplierId: { type: String, default: null },
  date: { type: Date, default: Date.now },
  method: { type: String, enum: ['cash', 'transfer'], default: 'cash' },
  note: str(),
  total: { type: Number, default: 0 },
  lines: { type: [Mixed], default: [] },
  ...stamps,
}, [[{ date: -1 }, {}]]);

// ---------- people ----------

const Customer = make('Customer', 'customers', {
  _id: String,
  name: { type: String, required: true },
  phone: { type: String, required: true },
  phoneKey: { type: String, required: true }, // digits only: the unique key used to match / merge customers
  allergy: str(),
  pref: str(),
  attention: str(),
  birthday: { type: String, default: null },
  points: { type: Number, default: 0 },
  search: str(),
  ...stamps,
}, [[{ phoneKey: 1 }, { unique: true }], [{ search: 1 }, {}]]);

const Promotion = make('Promotion', 'promotions', {
  _id: String,
  code: { type: String, required: true },
  kind: { type: String, enum: ['percent', 'amount'], required: true },
  value: { type: Number, required: true },
  minAmount: { type: Number, default: 0 },
  limit: { type: Number, default: 0 },
  used: { type: Number, default: 0 },
  end: { type: String, default: null },
  ...stamps,
}, [[{ code: 1 }, { unique: true }]]);

const Staff = make('Staff', 'staff', {
  _id: String,
  name: { type: String, required: true },
  phone: str(),
  role: { type: String, enum: ['waiter', 'kitchen', 'bar', 'cashier', 'delivery'], default: 'waiter' },
  joined: { type: String, default: null },
  active: { type: Boolean, default: true },
  note: str(),
  ...stamps,
});

// ---------- orders ----------

const Order = make('Order', 'orders', {
  _id: String,
  code: String,
  number: Number,
  day: String, // local date of openedAt (numbering)
  kind: { type: String, enum: ['dine', 'take', 'delivery'], required: true },
  status: { type: String, enum: ['open', 'closed', 'cancelled'], default: 'open' },
  version: { type: Number, default: 1 },
  tableId: { type: String, default: null },
  tableLabel: str(),
  customerId: { type: String, default: null },
  customerName: str(),
  phone: str(),
  party: { type: Number, default: 1 },
  note: str(),
  allergy: str(),
  address: str(),
  deliveryFee: { type: Number, default: 0 },
  deliveryStatus: { type: String, default: null },
  delivererId: { type: String, default: null },
  dueAt: { type: Date, default: null },
  serviceOn: { type: Boolean, default: false },
  surcharge: { type: Number, default: 0 },
  openedAt: { type: Date, default: Date.now },
  closedAt: { type: Date, default: null },
  openedBy: str(),
  cancelReason: str(),
  roundAdjust: { type: Number, default: 0 }, // chốt khi đóng
  finalTotal: { type: Number, default: null }, // total frozen at close
  rulesSnap: { type: Mixed, default: null }, // { servicePct, roundTo } frozen at close
  pointsAwarded: { type: Number, default: 0 },
  lines: { type: [Mixed], default: [] },
  discounts: { type: [Mixed], default: [] },
  payments: { type: [Mixed], default: [] },
  search: str(),
  ...stamps,
}, [
  [{ status: 1, openedAt: -1 }, {}],
  [{ closedAt: -1 }, {}],
  [{ tableId: 1, status: 1 }, {}],
  [{ customerId: 1 }, {}],
  [{ search: 1 }, {}],
  [{ 'payments.at': 1 }, {}],
]);

// ---------- bookings ----------

const Booking = make('Booking', 'bookings', {
  _id: String,
  name: { type: String, required: true },
  phone: str(),
  party: { type: Number, default: 1 },
  date: { type: String, required: true },
  startMin: { type: Number, required: true },
  durationMin: { type: Number, default: 90 },
  note: str(),
  areaPref: str(),
  deposit: { type: Number, default: 0 },
  status: { type: String, enum: ['booked', 'arrived', 'noshow', 'cancelled'], default: 'booked' },
  tableIds: { type: [String], default: [] },
  startAt: Date, // UTC instant of the start (overlap checks)
  endAt: Date, // start + duration + cleaning buffer
  search: str(),
  ...stamps,
}, [[{ date: 1, status: 1 }, {}], [{ tableIds: 1, status: 1, startAt: 1 }, {}]]);

const WaitEntry = make('WaitEntry', 'wait_list', { _id: String, name: { type: String, required: true }, phone: str(), party: { type: Number, default: 1 }, joinedAt: { type: Date, default: Date.now }, ...stamps });

// ---------- cash ----------

const Shift = make('Shift', 'shifts', {
  _id: String,
  openedBy: str(),
  openedAt: { type: Date, default: Date.now },
  closedAt: { type: Date, default: null },
  startCash: { type: Number, default: 0 },
  countedCash: { type: Number, default: null },
  expectedCash: { type: Number, default: null }, // frozen at close
  difference: { type: Number, default: null },
  ...stamps,
}, [[{ closedAt: 1 }, {}], [{ openedAt: -1 }, {}]]);

const CashEntry = make('CashEntry', 'cash_entries', {
  _id: String,
  shiftId: { type: String, required: true },
  amount: { type: Number, required: true },
  reason: { type: String, required: true },
  at: { type: Date, default: Date.now },
  ...stamps,
}, [[{ shiftId: 1, at: 1 }, {}]]);

const Expense = make('Expense', 'expenses', {
  _id: String,
  category: { type: String, required: true },
  amount: { type: Number, required: true },
  date: { type: String, required: true },
  recurring: { type: Boolean, default: false },
  note: str(),
  ...stamps,
}, [[{ date: 1 }, {}]]);

const SalesTarget = make('SalesTarget', 'sales_targets', { _id: String, targetRevenue: { type: Number, default: 0 }, ...stamps });

module.exports = {
  Account, Session, PasswordReset, Receipt, RateHit, Counter, Setting, AdminAction,
  Area, Table, MenuGroup, MenuItem, Ingredient, StockLot, StockMove, Supplier, Purchase,
  Customer, Promotion, Staff, Order, Booking, WaitEntry, Shift, CashEntry, Expense, SalesTarget,
};
